@ApplicationScoped
public class PaymentService {
    @Retry(maxRetries = 2)
    @Fallback(fallbackMethod = "degraded")
    public Result charge(Order order) { return gateway.call(order); }

    private Result degraded(Order order) { return Result.queued(order); }
}
